const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let identity={authenticated:false,cloudReady:false,user:null},sync=null,syncStatus={phase:'connecting',lastSync:null},figures=[],builtCourse,baseCourses=[],lessonOpen=false,searchQuery='',lessonFilter='all',noteTimer;
let profileDraft=null,profileBase=null,avatarPending=null,profileDirty=false,avatarProcessing=false;const avatarURLs=new Map(),avatarReads=new Set();
let db,courses=[],audioCatalog={},courseId='hsk-1',page='home',lessonIndex=0,lessonTab='guide',filter='all',fi=0,flipped=false,draft=null,busy=false,quiz=null,readerKind='textbook',readerPage=1,pdfCache=new Map(),renderToken=0;
let state={id:'main',known:{},done:{},notes:{},days:[],custom:[],last:{},legacy:null,resumes:{}};let toastTimer;let objectUrls=[];let readerRequest=0;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'Có lỗi khi xử lý. Hãy thử lại.');console.error(e.reason)});
const course=()=>courses.find(c=>c.id===courseId)||courses[0];const lesson=()=>course().lessons[lessonIndex]||course().lessons[0];const key=l=>courseId+':'+l.id;const wk=w=>cardKey(courseId,w);
const allWords=()=>allCourseWords(course(),state.custom);
const deck=()=>allWords().filter(w=>filter==='all'||filter==='unknown'&&!state.known[wk(w)]||filter==='lesson'&&w.lesson===lesson().number);

async function dbWrite(target,records){await writeLocal(target,records);if(sync&&target===db){const fileIds=records.filter(([kind])=>kind==='files').map(([,value])=>value.id);sync.capture(fileIds).catch(e=>console.warn('Local sync queue:',e.message))}}
const name=()=>state.profile?.displayName||identity.user?.name?.split('@')[0]?.split(' ').filter(Boolean).at(-1)||'Nam';

function profileDefaults(){return {displayName:(state.profile?.displayName||identity.user?.name?.split('@')[0]||'Nam').slice(0,60),fullName:(state.profile?.fullName??identity.user?.name??'').slice(0,100),contactEmail:state.profile?.contactEmail??identity.user?.email??'',location:state.profile?.location||'',bio:state.profile?.bio||'',avatarHash:state.profile?.avatarHash||''}}
function avatarInner(hash,initial){const safe=/^[a-f0-9]{64}$/.test(hash||'')?hash:'';const src=safe?(avatarURLs.get(safe)||(identity.authenticated?'/api/avatar/'+safe:'')):'';return `<span class="avatar-fallback" ${src?'hidden':''}>${esc(initial||'N')}</span>${src?`<img class="avatar-image" src="${esc(src)}" alt="Ảnh đại diện" data-avatar-hash="${safe}">`:''}`}
function avatarBlock(profile,cls='account-avatar'){return `<div class="${cls}" data-avatar-wrapper="${esc(profile.avatarHash||'')}">${avatarInner(profile.avatarHash,(profile.displayName||name())[0]?.toUpperCase())}</div>`}
async function hydrateAvatars(){document.querySelectorAll('.avatar-image').forEach(img=>img.onerror=()=>{img.hidden=true;const fallback=img.parentElement.querySelector('.avatar-fallback');if(fallback)fallback.hidden=false});const hashes=new Set([...document.querySelectorAll('[data-avatar-wrapper]')].map(el=>el.dataset.avatarWrapper).filter(h=>/^[a-f0-9]{64}$/.test(h)));for(const hash of hashes){if(avatarURLs.has(hash)||avatarReads.has(hash))continue;avatarReads.add(hash);try{const file=await dbGet(db,'files','avatar:'+hash);if(file?.blob){avatarURLs.set(hash,URL.createObjectURL(file.blob));document.querySelectorAll('[data-avatar-wrapper]').forEach(el=>{if(el.dataset.avatarWrapper===hash)el.innerHTML=avatarInner(hash,el.textContent.trim()||name()[0]?.toUpperCase())})}}finally{avatarReads.delete(hash)}}}
function collectProfileDraft(){if(!profileDraft){profileBase=profileDefaults();profileDraft={...profileBase}}const form=$('#profileForm');if(form)for(const [key,value]of new FormData(form))if(['displayName','fullName','contactEmail','location','bio'].includes(key))profileDraft[key]=String(value);return profileDraft}
function profileFormHTML(){const d=profileDraft||profileDefaults();return `<section class="panel profile-editor"><div class="section-head"><div><h2>Thông tin cá nhân</h2><p class="tiny" style="margin:5px 0 0">Tên và ảnh đại diện sẽ xuất hiện trong góc học của bạn.</p></div><span class="pill">Hồ sơ của bạn</span></div><form id="profileForm" class="form-stack"><div class="profile-photo-row">${avatarBlock(d,'profile-photo-preview')}<div><div class="row"><button type="button" class="secondary" id="chooseAvatar" ${avatarProcessing?'disabled':''}>${avatarProcessing?'Đang xử lý ảnh…':'＋ Chọn ảnh đại diện'}</button><button type="button" class="ghost" id="removeAvatar" ${!d.avatarHash?'hidden':''}>Xóa ảnh</button></div><p class="tiny" style="margin:8px 0 0">JPG, PNG hoặc WebP, tối đa 8 MB. Ảnh được cắt vuông từ giữa trước khi lưu.</p><input id="avatarFile" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Chọn tệp ảnh đại diện" hidden></div></div><div class="form-grid"><label>Tên hiển thị<input name="displayName" required maxlength="60" autocomplete="nickname" value="${esc(d.displayName)}" placeholder="Tên bạn muốn Hǎo gọi"></label><label>Họ và tên<input name="fullName" maxlength="100" autocomplete="name" value="${esc(d.fullName)}" placeholder="Họ và tên của bạn"></label><label>Email liên hệ<input name="contactEmail" type="email" maxlength="254" autocomplete="email" value="${esc(d.contactEmail)}" placeholder="ban@example.com"></label><label>Nơi ở<input name="location" maxlength="100" autocomplete="address-level2" value="${esc(d.location)}" placeholder="Ví dụ: TP. Hồ Chí Minh, Việt Nam"></label><label class="span-2">Giới thiệu ngắn<textarea name="bio" maxlength="500" rows="3" placeholder="Một chút về bạn hoặc mục tiêu học tiếng Trung…">${esc(d.bio)}</textarea></label></div><div class="profile-form-footer"><small id="profileSaveStatus" role="status">${profileDirty?'Bạn có thay đổi chưa lưu.':identity.authenticated?'Hồ sơ được đồng bộ cùng tài khoản đăng nhập.':'Đăng nhập để đồng bộ hồ sơ giữa các thiết bị.'}</small><div class="row"><button type="button" class="secondary" id="cancelProfile" ${!profileDirty?'hidden':''}>Hủy thay đổi</button><button id="saveProfile" ${avatarProcessing?'disabled':''}>Lưu hồ sơ</button></div></div></form></section>`}
async function onAvatarChange(event){const file=event.target.files?.[0];if(!file)return;collectProfileDraft();profileDirty=true;avatarProcessing=true;const button=$('#saveProfile');if(button)button.disabled=true;try{const image=await prepareAvatar(file);collectProfileDraft();profileDraft.avatarHash=image.hash;avatarPending=image;if(!avatarURLs.has(image.hash))avatarURLs.set(image.hash,URL.createObjectURL(image.blob));}catch(error){toast(error.message)}finally{avatarProcessing=false;render()}}
async function saveProfile(event){event.preventDefault();if(avatarProcessing)return;const button=$('#saveProfile');button.disabled=true;try{const draft=normalizeProfile(collectProfileDraft()),current=state.profile||{},values={};for(const key of Object.keys(draft))values[key]=!profileBase||draft[key]!==profileBase[key]||current[key]===undefined?draft[key]:current[key];const profile=normalizeProfile(values),next={...state,profile},records=[['state',next]];if(avatarPending&&profile.avatarHash===avatarPending.hash)records.push(['files',{id:'avatar:'+avatarPending.hash,name:'avatar.jpg',kind:'avatar',blob:avatarPending.blob}]);await dbWrite(db,records);state={...state,profile};profileDraft=null;profileBase=null;avatarPending=null;profileDirty=false;render();toast(identity.authenticated?'Đã lưu hồ sơ. Những thay đổi sẽ được đồng bộ vào tài khoản.':'Đã lưu hồ sơ trên thiết bị. Đăng nhập để đồng bộ.')}catch(error){toast(error.message);if($('#saveProfile'))$('#saveProfile').disabled=false}}
function profileUI(){const map={connecting:'Đang kết nối',syncing:'Đang đồng bộ',pending:'Đang chờ lưu',synced:'Đã đồng bộ',offline:'Đang ngoại tuyến',error:'Chờ kết nối lại',partial:'Còn tài liệu chờ tải',signedout:'Cần đăng nhập',guest:'Chưa đăng nhập'};const label=map[syncStatus.phase]||'Đã lưu trên thiết bị';$('#syncLabel').textContent=label;$('#sideSync').textContent=label;$('#syncChip').dataset.phase=syncStatus.phase;$('#profileButton').dataset.avatarWrapper=state.profile?.avatarHash||'';$('#profileButton').innerHTML=avatarInner(state.profile?.avatarHash,name()[0]?.toUpperCase()||'N');hydrateAvatars().catch(()=>{});}
async function openLesson(number){lessonIndex=course().lessons.findIndex(l=>l.number===+number);if(lessonIndex<0)lessonIndex=0;lessonOpen=true;lessonTab=isBundledVocabulary(course())?'words':'guide';readerKind='textbook';readerPage=lesson().start||1;page='lessons';state.resumes||={};state.resumes[courseId]=lesson().number;await persist();render();window.scrollTo(0,0)}
function mainFigure(number=lesson().number){return courseId==='hsk-1'?figures.find(f=>f.lesson===number&&!f.word):null}
function figureHTML(){const f=mainFigure();if(!f)return '';return `<figure class="figure-panel"><div class="eyebrow">HỌC QUA HÌNH ẢNH</div><button class="figure-image" data-figure="${esc(f.src)}" aria-label="Phóng to hình bài ${f.lesson}"><img src="/figures/${esc(f.src)}" alt="${esc(f.alt)}" loading="lazy"></button><figcaption>${esc(f.caption)} · Chạm hình để phóng to.</figcaption><button class="ghost" data-source-page="${f.sourcePage}">Đọc trang này trong sách →</button></figure>`}
function cardsHTML(){const list=course().lessons.filter(l=>(lessonFilter==='all'||lessonFilter==='done'&&isDone(l)||lessonFilter==='learning'&&!isDone(l))&&(!searchQuery||(l.title+' '+l.vi+' '+l.number+' '+(l.words||[]).map(w=>w.h+' '+w.v).join(' ')).toLocaleLowerCase('vi').includes(searchQuery.toLocaleLowerCase('vi'))));return list.length?list.map(l=>{const f=mainFigure(l.number);return `<button class="lesson-card" data-lesson="${l.number}"><div class="lesson-cover">${f?`<img src="/figures/${esc(f.src)}" alt="${esc(f.alt)}" loading="lazy">`:`<div class="cover-text">${esc(l.title?.match(/[\u4e00-\u9fff]/)?.[0]||'学')}</div>`}<span class="cover-number">BÀI ${String(l.number).padStart(2,'0')}</span>${isDone(l)?'<span class="cover-done">✓</span>':''}</div><div class="lesson-card-body"><h3>${esc(l.title)}</h3><p>${esc(l.vi||'Học cùng giáo trình của bạn')}</p><div class="lesson-card-meta"><span>${l.words?.length||0} từ trọng tâm</span><b>${isDone(l)?'Ôn lại':'Bắt đầu'} →</b></div></div></button>`}).join(''):'<div class="empty">Chưa tìm thấy bài phù hợp. Thử tên bài, từ tiếng Trung hoặc nghĩa tiếng Việt.</div>'}
function libraryHTML(){return `<div class="eyebrow">${esc(course().edition||course().name)}</div><h1>Từng bài nhỏ. Một hành trình dài.</h1><p>Chọn một bài, mở sách và bắt đầu theo nhịp của bạn.</p><div class="library-tools"><input id="lessonSearch" type="search" placeholder="Tìm tên bài hoặc từ vựng…" value="${esc(searchQuery)}" aria-label="Tìm trong giáo trình"><span class="pill">${course().lessons.filter(isDone).length} / ${course().lessons.length} bài hoàn thành</span></div><div class="tabs">${[['all','Tất cả bài học'],['learning','Đang học'],['done','Đã hoàn thành']].map(([k,t])=>`<button data-lesson-filter="${k}" class="${lessonFilter===k?'active':''}">${t}</button>`).join('')}</div><div class="lesson-grid" id="lessonGrid">${cardsHTML()}</div>`}
function homeHTML(){const c=course(),done=c.lessons.filter(isDone).length,known=allWords().filter(w=>state.known[wk(w)]).length;const resume=c.lessons.find(l=>l.number===state.resumes?.[courseId]);const next=resume&&!isDone(resume)?resume:c.lessons.find(l=>!isDone(l))||c.lessons[0];const todayWord=allWords().find(w=>!state.known[wk(w)])||allWords()[0];const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString('vi-VN',{weekday:'short'}),done:state.days.includes(d.toLocaleDateString('en-CA'))}});return `<div class="eyebrow">KHÔNG GIAN HỌC CỦA BẠN</div><div class="page-title-row"><div><h1>Chào ${esc(name())}, hôm nay học gì?</h1><p>Một chút mỗi ngày, để tiếng Trung trở nên gần gũi hơn.</p></div><div class="greeting-date">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</div></div><section class="hero"><div><div class="eyebrow">${esc(c.name)} · BÀI ${String(next.number).padStart(2,'0')}</div><h2>Một bài học nhỏ.<br>Một bước tiến mới.</h2><p>${esc(next.vi||next.title)}<br>Học từ câu quen thuộc, nghe thật chậm, và nhớ theo cách của bạn.</p><button class="light" data-lesson="${next.number}">${done||resume?'Tiếp tục học':'Bắt đầu học'} <span>→</span></button></div><div class="hero-art" aria-hidden="true"><div class="art-float one">你好 · nǐ hǎo</div><div class="book-art"><b>学</b><small>HỌC TỪNG CHÚT MỘT</small></div><div class="art-float two">✦ Mỗi ngày một chút</div><span class="art-spark">✧</span></div></section><div class="stats"><div class="stat"><span class="symbol">▱</span><div><b>${known}<small> / ${allWords().length}</small></b><label>Từ đã ghi nhớ</label></div></div><div class="stat"><span class="symbol">✓</span><div><b>${done}<small> / ${c.lessons.length}</small></b><label>Bài đã hoàn thành</label></div></div><div class="stat"><span class="symbol">☀</span><div><b>${state.days.length}<small> ngày</small></b><label>Cùng tiếng Trung</label></div></div></div><div class="grid-2"><section class="panel"><div class="section-head"><h2>Những bài học tiếp theo</h2><button class="ghost" data-go="lessons">Xem tất cả →</button></div>${lessonRows(c.lessons.slice(Math.max(0,c.lessons.indexOf(next)-1),Math.max(0,c.lessons.indexOf(next)-1)+4))}</section><div><section class="panel"><div class="section-head"><h2>Một từ cho hôm nay</h2><span class="pill">HSK ${esc(c.level)}</span></div>${todayWord?`<div class="today-word"><div class="hanzi">${esc(todayWord.h)}</div><div class="pin">${esc(todayWord.p)}</div><p>${esc(todayWord.v)}</p></div><div class="row end"><span class="tiny muted">Thử nhớ, rồi lật thẻ.</span><button class="ghost" data-go="flash">Ôn tập →</button></div>`:'<p class="tiny">Thêm từ riêng để ôn tập mỗi ngày.</p>'}</section><section class="panel"><div class="section-head"><h2>Giữ một nhịp học nhỏ</h2><span class="tiny muted">7 ngày gần đây</span></div><div class="weekdays">${week.map(d=>`<span class="${d.done?'studied':''}">${d.label}<i>${d.done?'✓':'·'}</i></span>`).join('')}</div></section></div></div>`}
function accountHTML(){const labels={connecting:'Đang kết nối tài khoản',syncing:'Đang đồng bộ',pending:'Đã lưu, đang chờ đồng bộ',synced:'Mọi thứ đã được đồng bộ',offline:'Đang ngoại tuyến',error:'Thay đổi được giữ trên thiết bị',partial:'Tiến độ đã được đồng bộ',signedout:'Phiên đăng nhập cần được làm mới',guest:'Đăng nhập để học trên mọi thiết bị'};return `<div class="eyebrow">CÙNG MỘT HÀNH TRÌNH, TRÊN MỌI THIẾT BỊ</div><h1>Góc học đi cùng bạn.</h1><p>Đăng nhập bằng cùng một email đã được cấp quyền trên điện thoại và máy tính.</p><div class="grid-2"><section class="panel"><div class="account-hero">${avatarBlock(profileDefaults())}<div><h2>${esc(state.profile?.displayName||identity.user?.name||'Chào bạn!')}</h2><p>${identity.authenticated?'Email đăng nhập: '+esc(identity.user.email):'Kết nối tài khoản để giữ hành trình học của bạn.'}</p></div></div>${identity.authenticated?`<span class="pill">Đã đăng nhập bằng email</span>`:`<a class="link-btn" href="${esc(identity.signIn||'/')}" target="_top">Đăng nhập bằng email →</a>`}<div class="cloud-state"><span class="cloud-symbol">☁</span><div><b>${labels[syncStatus.phase]||labels.guest}</b><p>${esc(syncStatus.detail||(syncStatus.lastSync?'Lần gần nhất: '+new Date(syncStatus.lastSync).toLocaleString('vi-VN'):'Tiến độ và ghi chú sẽ theo bạn qua các thiết bị.'))}</p></div></div>${identity.authenticated?`<div class="row end"><button id="syncNow" ${syncStatus.phase==='syncing'?'disabled':''}>↻ Đồng bộ ngay</button><a class="account-signout" href="${esc(identity.signOut||'/cdn-cgi/access/logout')}" target="_top">Đăng xuất ↗</a></div>`:''}<div class="callout tiny">Khi mất mạng, thay đổi vẫn được lưu trên thiết bị. Giữ trang mở khi có mạng để gửi những thay đổi đang chờ. Nếu cùng sửa một ghi chú trên hai thiết bị, bản chỉnh sửa có thời điểm mới hơn sẽ được dùng.</div></section><div>${profileFormHTML()}<section class="panel"><h2>Những gì được đồng bộ</h2><ul class="sync-features"><li>Hồ sơ cá nhân và ảnh đại diện</li><li>Tiến độ bài học và từ đã ghi nhớ</li><li>Ghi chú và bộ từ vựng của bạn</li><li>Giáo trình mới và nội dung đã nhập</li><li>PDF riêng lưu trên thiết bị và chuyển bằng ZIP</li></ul><p class="tiny">Tiến độ, ghi chú, nội dung bài học và ảnh đại diện được đồng bộ. PDF riêng không tải lên máy chủ; dùng bản sao lưu ZIP để chuyển giữa các thiết bị.</p></section><section class="panel"><h2>Dữ liệu cũ vẫn ở đây.</h2><p class="tiny">Dữ liệu từ phiên bản trước trên trình duyệt này được chuyển sang tài khoản khi đăng nhập lần đầu. Bạn vẫn có thể tạo một bản sao lưu riêng.</p><button class="secondary" data-go="notebook">Mở sổ tay & sao lưu →</button></section></div></div>`}
async function persist(){await dbWrite(db,[['state',state]])}
async function touch(){const d=dayKey();if(!state.days.includes(d))state.days.push(d);await persist()}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.textContent='↓ Tải '+name;a.className='link-btn';const box=document.createElement('div');box.className='download-ready';box.append('Tệp đã sẵn sàng. ',a);document.querySelectorAll('.download-ready').forEach(x=>x.remove());document.body.append(box);a.click();setTimeout(()=>{URL.revokeObjectURL(u);box.remove()},300000)}
function jsonDownload(obj,name){download(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),name)}
function isDone(l){return !!state.done[key(l)]}
function lessonRows(list=course().lessons){return list.map(l=>`<div class="lessonrow"><div class="num">${isDone(l)?'✓':String(l.number).padStart(2,'0')}</div><div><b>${esc(l.title)}</b><small>${esc(l.vi||'Bài từ giáo trình của bạn')} · ${l.words?.length||0} từ trọng tâm${l.printedStart?' · tr. '+l.printedStart:''}</small></div><button class="secondary" data-lesson="${l.number}" aria-label="Mở bài ${l.number}">↗</button></div>`).join('')}
function selectOptions(){return course().lessons.map((l,i)=>`<option value="${i}" ${i===lessonIndex?'selected':''}>${String(l.number).padStart(2,'0')} · ${esc(l.title)}${l.vi?' — '+esc(l.vi):''}</option>`).join('')}
function tracks(kind){if(isBundledVocabulary(course()))return [];const byCatalog=course().syllabus==='hsk2'?[]:audioCatalog[course().level+'-'+kind]?.[String(lesson().number).padStart(2,'0')]||[];return kind==='textbook'?[...byCatalog,...(lesson().audio||[])]:byCatalog}
async function go(p){if(busy&&p!=='import'){toast('Hãy đợi nhập xong hoặc nhấn Dừng trước khi chuyển trang.');return}await studyLab.expireAttempts();page=p;if(p==='lessons')lessonOpen=false;if(p==='quiz')quiz=null;render();window.scrollTo(0,0)}
function header(){document.querySelectorAll('nav [data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===page));$('#crumb').textContent={home:'Tổng quan',lessons:'Bài học',flash:'Flashcard',quiz:'Tự kiểm tra',import:'Thêm giáo trình',notebook:'Sổ tay',account:'Tài khoản',...studyLab.routes}[page];profileUI();$('#headerLevel').textContent='HSK '+course().level.toUpperCase();$('#courseSelect').innerHTML=courses.map(c=>`<option value="${esc(c.id)}" ${c.id===courseId?'selected':''}>${esc(c.name)}</option>`).join('')}
function render(){studyLab.cleanup();renderToken++;for(const u of objectUrls)URL.revokeObjectURL(u);objectUrls=[];header();let html='';const c=course(),l=lesson();
 if(page==='home')html=homeHTML();
 if(page==='lessons'&&!lessonOpen)html=libraryHTML();
 if(page==='lessons'&&lessonOpen){
 html=`<div class="eyebrow">${esc(c.name)}</div><h1>${esc(l.vi||l.title)}</h1><p>${esc(l.title)}${l.printedStart?' · Giáo trình trang '+l.printedStart:''}</p><div class="lesson-select"><select id="lessonSelect" aria-label="Chọn bài học">${selectOptions()}</select><span class="count-tag">${lessonIndex+1} / ${c.lessons.length}</span></div><div class="tabs">${[['guide','01 · Hiểu bài'],['words','02 · Từ vựng'],['audio','03 · Luyện nghe'],['reader','04 · Đọc sách'],['writing','05 · Tập viết']].map(([t,s])=>`<button data-tab="${t}" class="${t===lessonTab?'active':''}">${s}</button>`).join('')}</div>`;
 if(lessonTab==='guide')html+=`<div class="study-layout"><section class="panel"><div class="section-head"><h2>Hiểu mẫu câu bằng tiếng Việt</h2><span class="pill">${c.builtIn?'Biên soạn hỗ trợ học':'Nội dung giáo trình'}</span></div>${l.grammar?.length?l.grammar.map(g=>`<div class="grammar"><h3>${esc(g.title)}</h3><p>${esc(g.explanation)}</p><div class="example"><b>${esc(g.h)}</b><br><span class="pin">${esc(g.p)}</span><br>${esc(g.v)}</div></div>`).join(''):`<div class="empty"><h3>Bắt đầu từ trang sách</h3><p class="tiny">Bài đã được nhập từ PDF. Nhận dạng chữ không tự tạo bản dịch hoặc lời giải tiếng Việt.</p><button data-tab="reader">Mở sách gốc →</button></div><p class="tiny">Bạn có thể nhập gói JSON đã biên soạn để bổ sung giải thích, từ vựng và ví dụ cho cùng cấp HSK.</p>`}${l.rawText?`<details style="margin-top:20px"><summary>Văn bản nhận dạng từ PDF (có thể sai)</summary><pre class="rawtext">${esc(l.rawText)}</pre></details>`:''}<div class="callout tiny">${esc(l.sourceNote||'Đối chiếu với trang sách gốc khi nhận dạng chữ có lỗi.')}<br>Gợi ý: hiểu mẫu câu → nghe lại → thay từ để tự đặt một câu của bạn.</div></section>${figureHTML()}</div>`;
 if(lessonTab==='words')html+=`<section class="panel"><div class="section-head"><h2>Từ trọng tâm · ${l.words?.length||0}</h2><button class="secondary" id="flashLesson">Ôn bộ thẻ bài này →</button></div>${l.words?.length?l.words.map(wordHTML).join(''):'<div class="empty">Chưa có bộ từ cho bài này. Thêm ở Sổ tay hoặc nhập gói JSON có từ vựng.</div>'}${isBundledVocabulary(c)?'<p class="tiny">Bộ từ theo đề cương được cập nhật từ nguồn. Dùng Sổ tay để thêm từ riêng của bạn.</p>':`<details style="margin-top:20px"><summary>Nhập thêm từ vào bài bằng văn bản</summary><p class="tiny">Mỗi dòng: Chữ Hán [Tab] Pinyin [Tab] Nghĩa [Tab] Câu ví dụ [Tab] Dịch câu. Ba cột đầu bắt buộc.</p><textarea id="wordLines" placeholder="学习&#9;xuéxí&#9;học tập"></textarea><button id="saveWordLines" style="margin-top:10px">Thêm từ vào bài</button></details>`}</section>`;
 if(lessonTab==='audio')html+=audioHTML();
 if(lessonTab==='reader')html+=readerHTML();
 if(lessonTab==='writing')html+=`<section class="panel"><h2>Viết chậm, nhớ mặt chữ</h2><p class="tiny">Ô bên dưới là giấy nháp tự luyện, chưa chấm thứ tự nét. Xem mẫu nét trong tệp tập viết gốc.</p><div class="row"><label>Chữ muốn luyện<input id="practiceChar" value="${esc(l.words?.[0]?.h?.[0]||'学')}" maxlength="2"></label><button class="secondary" id="clearDraw">Xóa nét</button></div><canvas id="drawCanvas" class="draw-area" width="800" height="800" aria-label="Ô viết chữ bằng chuột hoặc cảm ứng"></canvas></section>${c.documents?.writing?readerHTML('writing'):''}`;
 html+=`<section class="panel"><label for="lessonNotes">Ghi chú của riêng bạn</label><textarea id="lessonNotes" class="notes" placeholder="Một câu mình tự đặt, một điểm dễ nhầm…">${esc(state.notes[key(l)]||'')}</textarea><div class="row end" style="margin-top:12px"><small id="noteStatus">Lưu khi nhấn nút</small><button id="saveNote" class="secondary">Lưu ghi chú</button></div></section><div class="actions"><button id="doneLesson">${isDone(l)?'✓ Đã hoàn thành · Bỏ đánh dấu':'✓ Đánh dấu đã học'}</button>${lessonIndex<c.lessons.length-1?'<button id="nextLesson" class="secondary">Bài tiếp →</button>':''}</div>`;
 }
 if(page==='flash'){
 const d=deck();fi=d.length?((fi%d.length)+d.length)%d.length:0;const w=d[fi];
 html=`<div class="eyebrow">ÔN TẬP CHỦ ĐỘNG · HSK ${esc(c.level)}</div><h1>Lật thẻ, nhớ thêm một từ.</h1><p>Thử nhớ trước khi lật. Dùng phím ← → để chuyển thẻ.</p><div class="tabs">${[['all','Tất cả'],['unknown','Chưa nhớ'],['lesson','Bài '+l.number]].map(([f,t])=>`<button data-filter="${f}" class="${filter===f?'active':''}">${t}</button>`).join('')}</div><section class="panel">${w?`<div class="section-head"><span>Thẻ ${fi+1} / ${d.length}</span><span class="pill">${state.known[wk(w)]?'✓ Đã nhớ':'Đang học'}</span></div><button class="flash" id="flip"><strong>${esc(flipped?w.v:w.h)}</strong><span class="pin">${esc(flipped?w.p:'Chạm để xem nghĩa')}</span>${flipped&&w.ex?`<span class="tiny">${esc(w.ex)}<br>${esc(w.ev)}</span>`:''}</button><div class="actions"><button class="secondary" id="prevCard">← Trước</button><button class="secondary" data-speak="${esc(w.h)}">◖ Nghe máy đọc</button><button id="remember">${state.known[wk(w)]?'Học lại từ này':'✓ Tôi đã nhớ'}</button><button class="secondary" id="nextCard">Tiếp →</button></div>`:'<div class="empty"><h2>Chưa có từ trong bộ thẻ này</h2><p class="tiny">Chọn bộ khác hoặc thêm từ ở Sổ tay.</p><button data-go="notebook">Thêm từ</button></div>'}</section>`;
 }
 if(page==='quiz'){
 const ws=allWords();if(ws.length<4){html='<h1>Tự kiểm tra</h1><div class="panel empty">Cần ít nhất 4 từ có nghĩa khác nhau để tạo câu hỏi. Hãy bổ sung từ ở Sổ tay.</div>'}else{
 if(!quiz){const unique=[...new Map(ws.map(w=>[w.v,w])).values()];quiz={words:shuffle(unique).slice(0,10),pool:unique,index:0,score:0,answered:false,finished:false}}
 if(quiz.pool.length<4)html='<h1>Tự kiểm tra</h1><div class="panel empty">Cần ít nhất 4 nghĩa từ khác nhau.</div>';
 else if(quiz.finished)html=`<section class="panel center"><div class="hanzi">好！</div><h1>${quiz.score} / ${quiz.words.length} câu đúng</h1><p>Thêm một lượt ôn, thêm một chút tự tin.</p><div class="actions"><button id="retryQuiz">Làm lại</button><button class="secondary" data-go="flash">Ôn flashcard</button></div></section>`;
 else{const w=quiz.words[quiz.index];quiz.options=shuffle([w,...shuffle(quiz.pool.filter(v=>v.v!==w.v)).slice(0,3)]);html=`<div class="eyebrow">TỰ KIỂM TRA · HSK ${esc(c.level)}</div><h1>Thử nhớ, rồi kiểm tra.</h1><p>Câu hỏi được tạo từ bộ từ của giáo trình đang chọn.</p><section class="panel"><div class="section-head"><span>Câu ${quiz.index+1} / ${quiz.words.length}</span><span id="quizScore" class="pill">${quiz.score} câu đúng</span></div><progress value="${quiz.index}" max="${quiz.words.length}"></progress><div class="hanzi center">${esc(w.h)}</div><div class="pin center" style="margin-bottom:25px">${esc(w.p)}</div><div class="answer-grid">${quiz.options.map((x,i)=>`<button data-answer="${i}">${esc(x.v)}</button>`).join('')}</div><div id="feedback" role="status"></div><div class="actions"><button id="nextQuestion" hidden>${quiz.index===quiz.words.length-1?'Xem kết quả':'Câu tiếp →'}</button></div></section>`}
 }
 }
 if(page==='import')html=importHTML();
 if(page==='notebook')html=notebookHTML();
 if(page==='account')html=accountHTML();
 if(studyLab.has(page))html=studyLab.html(page);if(page==='home')html+=studyLab.homeHTML();
 $('#view').innerHTML=html;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#view').animate([{opacity:.3,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:270,easing:'ease-out'});bind();studyLab.bind(page);if(page==='lessons'&&lessonOpen&&lessonTab==='reader')loadReader();if(page==='lessons'&&lessonOpen&&lessonTab==='writing'){initDrawing();if(c.documents?.writing)loadReader('writing')}
}
function wordPicture(w){const f=courseId==='hsk-1'?figures.find(f=>f.word===w.h):null;return f?`<button class="word-picture" data-figure="${esc(f.src)}" aria-label="Phóng to hình ${esc(w.h)}"><img src="/figures/${esc(f.src)}" alt="${esc(f.alt)}" loading="lazy"></button>`:''}
function wordHTML(w){return `<div class="word"><div class="han">${esc(w.h)}</div><div><div class="pin">${esc(w.p)}</div><b>${esc(w.v)}</b>${wordPicture(w)}${w.ex?`<div class="example"><b>${esc(w.ex)}</b><br>${esc(w.ep||'')}<br>${esc(w.ev||'')}</div>`:''}</div><button class="secondary" data-speak="${esc(w.h)}" aria-label="Nghe máy đọc ${esc(w.h)}">◖</button></div>`}
function audioHTML(){if(isBundledVocabulary(course()))return '<section class="panel"><h2>Nghe từ vựng</h2><p>Nhấn biểu tượng ◖ cạnh từng từ hoặc trong flashcard để nghe giọng máy. Bộ từ theo đề cương chưa kèm bản thu âm giáo trình.</p></section>';return `<section class="panel"><div class="section-head"><h2>Nghe cùng bài ${lesson().number}</h2><a class="link-btn" href="${esc(safeUrl(course().audioSource))}" target="_blank" rel="noopener">Nguồn audio ↗</a></div><p class="tiny">Nghe một lượt, đọc theo sách, rồi nghe lại. Số track giữ theo nguồn để bạn đối chiếu ký hiệu trong sách.</p><div class="audio-options"><label for="audioSpeed">Tốc độ</label><select id="audioSpeed"><option value=".75">0,75×</option><option value="1" selected>1×</option><option value="1.25">1,25×</option></select><label style="display:flex;align-items:center;gap:7px"><input type="checkbox" id="audioLoop" style="width:auto">Lặp đoạn</label></div>${['textbook','workbook'].map(k=>`<h3 style="margin-top:24px">${k==='textbook'?'Giáo trình':'Sách bài tập'}</h3>${tracks(k).length?tracks(k).map(t=>`<div class="audio-row"><span class="tiny">Track ${esc(t.label)}</span><audio controls preload="none" src="${esc(safeUrl(t.url))}"></audio></div>`).join(''):'<p class="tiny">Chưa có audio cho cấp / bài này trong danh mục.</p>'}`).join('')}<p class="tiny muted" style="margin-top:20px">Audio phát trực tiếp từ Baúl Chino, cần Internet. Nếu trình phát báo lỗi, mở nguồn audio bên trên.</p><div id="audioError" class="callout warning" hidden>Không tải được audio này. Hãy kiểm tra kết nối hoặc mở Nguồn audio.</div><details><summary>Gắn thêm một audio cho bài</summary><form id="addAudio" class="form-stack" style="margin-top:16px"><label>Tên đoạn<input name="label" required maxlength="180" placeholder="Bài 1 · Hội thoại"></label><label>Đường dẫn MP3 (https)<input name="url" type="url" required placeholder="https://…"></label><button>Lưu audio</button></form></details></section>`}
function readerHTML(force){const c=course();let k=force||readerKind;if(!c.documents?.[k])k=Object.keys(c.documents||{})[0];return `<section class="panel"><div class="section-head"><h2>${force?'Tệp tập viết gốc':'Đọc sách gốc'}</h2>${!force?`<select id="readerKind" style="max-width:230px" aria-label="Loại sách">${Object.keys(c.documents||{}).map(k=>`<option value="${k}" ${k===readerKind?'selected':''}>${{textbook:'Giáo trình',workbook:'Sách bài tập',writing:'Tập viết'}[k]||k}</option>`).join('')}</select>`:''}</div>${k?`<div class="reader-toolbar"><button class="secondary" id="prevPage">← Trang trước</button><div class="row"><label for="pageNumber" class="tiny">Trang PDF</label><input id="pageNumber" type="number" min="1" max="${c.documents[k].count}" value="${Math.min(readerPage,c.documents[k].count)}"><span class="tiny">/ ${c.documents[k].count}</span><button id="jumpPage" class="secondary">Đi</button></div><button class="secondary" id="nextPage">Trang sau →</button></div><p class="tiny muted">${esc(c.documents[k].name)} · Số trang PDF có thể khác số in trong sách.</p><div class="reader-frame" id="readerFrame">Đang mở trang sách…</div>`:'<div class="empty">Chưa có PDF gắn vào gói này. Thêm PDF qua mục Thêm giáo trình, chọn cùng cấp HSK.</div>'}</section>`}
async function loadReader(force){const request=++readerRequest,token=renderToken,k=force||readerKind,doc=course().documents?.[k],frame=$('#readerFrame');if(!doc||!frame)return;readerPage=Math.max(1,Math.min(readerPage,doc.count));$('#pageNumber').value=readerPage;try{if(doc.kind==='images'){frame.innerHTML=`<img src="${esc(doc.base+readerPage+'.webp')}" alt="${esc(doc.name)} · trang PDF ${readerPage}" loading="eager">`;return}let pdf=pdfCache.get(doc.fileId);if(!pdf){const f=await dbGet(db,'files',doc.fileId)||await sync?.ensureFile(doc.fileId);if(!f)throw Error('Thiếu tệp PDF trên thiết bị này. Hãy nhập lại PDF hoặc khôi phục bản sao lưu đầy đủ.');pdf=await openPdf(f.blob,true);pdfCache.set(doc.fileId,pdf)}if(token!==renderToken||request!==readerRequest)return;const canvas=document.createElement('canvas');await renderPdfPage(pdf,readerPage,canvas,1400);if(token!==renderToken||request!==readerRequest)return;frame.replaceChildren(canvas)}catch(e){frame.textContent=e.message}}
function importHTML(){
 if(draft)return reviewHTML();
 return `<div class="eyebrow">GIÁO TRÌNH TIẾP THEO, CÙNG MỘT GÓC HỌC</div><h1>Thêm cấp HSK của bạn.</h1><p>Nhập tài liệu → kiểm tra cách chia bài → bắt đầu học.</p><div class="steps"><b>01 · Chọn tài liệu</b><span>02 · Xem trước</span><span>03 · Cập nhật bài học</span></div><div class="grid-2"><section class="panel"><h2>Nhập PDF giáo trình</h2><form id="pdfImport" class="form-stack"><div class="form-grid"><label>Cấp HSK<select name="level">${['1','2','3','4','4a','4b','5','6','7','8','9'].map(n=>`<option ${n==='2'?'selected':''}>${n}</option>`).join('')}</select></label><label>Chuẩn của gói<select name="syllabus"><option value="unspecified">Chưa xác định</option><option value="hsk2">HSK 2.0</option><option value="hsk3">HSK 3.0</option></select></label><label>Tên giáo trình<input name="name" required maxlength="160" placeholder="HSK 2 · Giáo trình mới"></label></div><label class="upload-zone">▤ Giáo trình chính (PDF)<input name="book" type="file" accept="application/pdf,.pdf" required></label><div class="form-grid"><label>Sách bài tập (tùy chọn)<input name="workbook" type="file" accept="application/pdf,.pdf"></label><label>Tập viết (tùy chọn)<input name="writing" type="file" accept="application/pdf,.pdf"></label></div><label style="display:flex;align-items:flex-start;gap:10px"><input type="checkbox" name="ocr" style="width:auto;margin-top:4px"><span>Nhận dạng chữ trong bản scan (OCR)<br><small>Chậm hơn, có thể mất vài phút. Kết quả cần kiểm tra. Nếu bỏ chọn, PDF scan vẫn được lưu và bạn tự chia bài.</small></span></label><div class="callout tiny" style="margin:0">PDF có lớp chữ sẽ được đọc tự động. PDF scan cần OCR để tìm tiêu đề; nếu không tìm thấy, bạn có thể nhập tên bài và trang thủ công. Bảng từ có cột rõ ràng sẽ được trích thử thành thẻ theo nghĩa trong nguồn. Bạn kiểm tra lại rồi bổ sung bản dịch và giải thích tiếng Việt qua Sổ tay hoặc gói JSON.</div><button id="startImport">Đọc PDF và đề xuất bài học →</button><button type="button" class="danger" id="cancelImport" hidden>Dừng nhập</button><progress id="importProgress" hidden max="100" value="0"></progress><div class="import-log" id="importLog" hidden aria-live="polite"></div></form></section><div><section class="panel"><h2>Nhập gói bài học đã biên soạn</h2><p class="tiny">Gói JSON có thể gồm từ vựng, pinyin, ví dụ, giải thích và audio. Cập nhật cùng cấp sẽ giữ tiến độ và ghi chú theo số bài.</p><label>Chọn gói JSON<input type="file" id="jsonImport" accept="application/json,.json"></label><button id="getTemplate" class="ghost" style="margin-top:14px">↓ Tải mẫu gói JSON</button></section><section class="panel"><h2>Đã có trong góc học</h2>${courses.map(c=>`<div class="pack-card"><b>${esc(c.name)}</b><p>${c.lessons.length} bài · ${Object.keys(c.documents||{}).length} tài liệu · ${c.builtIn?'Tích hợp sẵn':'Giáo trình của bạn'}</p><button class="secondary" data-switch="${esc(c.id)}">Mở giáo trình</button></div>`).join('')}<p class="tiny" style="margin:0">Nhập cấp mới sẽ thêm giáo trình mới. Nhập cùng cấp sẽ hiện bản xem trước cập nhật trước khi lưu.</p></section></div></div>`}
function reviewHTML(){const c=draft.course,exists=courses.find(x=>x.id===c.id);return `<div class="eyebrow">BƯỚC 02 · KIỂM TRA TRƯỚC KHI LƯU</div><h1>${esc(c.name)}</h1><p>HSK ${esc(c.level)} · ${c.lessons.length} bài${draft.files.length?' · '+draft.files.length+' PDF':''}</p>${exists?'<div class="callout warning">Cấp HSK này đã tồn tại. Bản cập nhật sẽ thay danh sách bài theo bản xem trước; từ vựng và giải thích đã có được giữ nếu bài nhập không có phần đó. Tiến độ, ghi chú và cấp HSK khác vẫn được giữ.</div>':''}${!draft.hasText&&draft.files.length?'<div class="callout warning">PDF không có lớp chữ và chưa nhận dạng được nội dung. Bạn vẫn có thể đọc sách và tự chia bài bằng các dòng bên dưới.</div>':''}<section class="panel"><div class="section-head"><h2>${draft.files.length?'Tên bài và phạm vi trang PDF':'Nội dung gói bài học'}</h2><button class="secondary" id="addDraftLesson">＋ Thêm dòng bài</button></div><p class="tiny">Tên bài và số trang là bản đề xuất, cần đối chiếu mục lục. Phạm vi trang dùng số trang PDF, tính từ 1.</p><div class="review-table"><table><thead><tr><th>Bài</th><th>Tên bài</th><th>Từ</th><th>Từ trang</th><th>Đến trang</th><th></th></tr></thead><tbody>${c.lessons.map((l,i)=>`<tr data-draft="${i}"><td><input data-field="number" type="number" min="1" max="999" value="${l.number}" aria-label="Số bài dòng ${i+1}"></td><td><input data-field="title" value="${esc(l.title)}" aria-label="Tên bài dòng ${i+1}"></td><td>${l.words?.length||0}</td><td><input data-field="start" type="number" min="1" value="${l.start||1}" aria-label="Trang đầu dòng ${i+1}"></td><td><input data-field="end" type="number" min="1" value="${l.end||l.start||1}" aria-label="Trang cuối dòng ${i+1}"></td><td><button class="ghost" data-remove-draft="${i}" aria-label="Bỏ bài dòng ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div><div class="callout tiny">Sau khi lưu, bài được thêm vào danh sách, bộ chọn cấp HSK và phần đọc sách. Gói có từ vựng sẽ đồng thời cập nhật flashcard và câu hỏi. Nhận dạng PDF không tự tạo bản dịch hoặc lời giải.</div>${c.lessons.some(l=>l.words?.length)?`<details style="margin-bottom:20px"><summary>Xem từ vựng sắp nhập (kiểm tra nghĩa theo nguồn)</summary>${c.lessons.filter(l=>l.words?.length).map(l=>`<h3 style="margin-top:15px">Bài ${l.number}</h3>${l.words.map(w=>`<p class="tiny">${esc(w.h)} · ${esc(w.p)} · ${esc(w.v)}</p>`).join('')}`).join('')}</details>`:''}<div class="row"><button id="commitImport">${exists?'Cập nhật cấp HSK này':'Thêm cấp HSK và bắt đầu học'} →</button><button class="secondary" id="discardDraft">Quay lại chọn tệp</button></div></section>`}
function notebookHTML(){const custom=state.custom.filter(w=>w.courseId===courseId);return `<div class="eyebrow">TỪ VÀ Ý TƯỞNG CỦA RIÊNG BẠN</div><h1>Sổ tay & sao lưu</h1><p>Tiến độ, ghi chú và từ riêng được lưu vào tài khoản khi đăng nhập. Bạn vẫn có thể giữ một bản sao lưu riêng.</p><div class="grid-2"><section class="panel"><h2>Thêm một từ · HSK ${esc(course().level)}</h2><form id="addWord" class="form-grid"><label>Chữ Hán<input name="h" required maxlength="80" placeholder="学习"></label><label>Pinyin<input name="p" required maxlength="180" placeholder="xuéxí"></label><label class="span-2">Nghĩa tiếng Việt<input name="v" required maxlength="300" placeholder="học tập"></label><label class="span-2">Câu ví dụ<input name="ex" maxlength="500" placeholder="我学习汉语。"></label><label class="span-2">Dịch câu<input name="ev" maxlength="600" placeholder="Tôi học tiếng Trung."></label><button class="span-2">＋ Thêm vào flashcard</button></form><div class="divider"></div><h2>Từ của bạn · ${custom.length}</h2>${custom.length?custom.map(w=>`<div class="lessonrow"><div><b>${esc(w.h)} · ${esc(w.p)}</b><small>${esc(w.v)}</small></div><button class="ghost" data-delete-word="${esc(w.id)}" aria-label="Xóa từ ${esc(w.h)}">×</button></div>`).join(''):'<p class="tiny">Bắt đầu với một từ bạn muốn nhớ thêm.</p>'}</section><div><section class="panel"><h2>Mang góc học sang thiết bị khác</h2><p class="tiny">Bản sao lưu ZIP gồm giáo trình đã nhập, PDF hiện có trên thiết bị, tiến độ, từ riêng và ghi chú. Tài liệu HSK 1 tích hợp sẵn sẽ tự có lại khi mở trang.</p><button id="backup">↓ Tạo bản sao lưu đầy đủ (.zip)</button><label style="margin-top:20px">Khôi phục bản sao lưu<input type="file" id="restore" accept=".zip,application/zip"></label><p class="tiny" id="backupStatus">Khôi phục sẽ ghép các giáo trình và tiến độ. Khi trùng ghi chú hoặc tài liệu, bản sao lưu được ưu tiên.</p></section><section class="panel"><h2>Xuất gói bài học</h2><p class="tiny">Xuất nội dung ${esc(course().name)} dưới dạng JSON để biên soạn hoặc bổ sung. Gói JSON không chứa PDF và tiến độ.</p><button class="secondary" id="exportCourse">↓ Tải gói bài học JSON</button></section>${state.legacy?`<section class="panel"><h2>Dữ liệu từ phiên bản trước</h2><p class="tiny">Đã giữ ${state.legacy.done?.length||0} bài mẫu hoàn thành và chuyển từ riêng sang sổ tay. Kết quả bài mẫu cũ không tính thành hoàn thành bài giáo trình mới.</p></section>`:''}</div></div>`}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function speak(t){if(!('speechSynthesis'in window)){toast('Trình duyệt chưa hỗ trợ giọng đọc. Mở Luyện nghe để nghe audio giáo trình.');return}const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('zh'));if(!voice){toast('Thiết bị chưa có giọng tiếng Trung. Dùng audio giáo trình trong Luyện nghe.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.voice=voice;u.lang='zh-CN';u.rate=.75;speechSynthesis.speak(u)}
function initDrawing(){const el=$('#drawCanvas');if(!el)return;const ctx=el.getContext('2d');const drawGuide=()=>{ctx.clearRect(0,0,800,800);ctx.fillStyle='#e5eadb';ctx.font='510px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText($('#practiceChar').value||'学',400,415)};drawGuide();$('#practiceChar').oninput=drawGuide;$('#clearDraw').onclick=drawGuide;let down=false;function pt(e){const r=el.getBoundingClientRect();return [(e.clientX-r.left)*800/r.width,(e.clientY-r.top)*800/r.height]}el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);down=true;ctx.beginPath();ctx.moveTo(...pt(e))};el.onpointermove=e=>{if(!down)return;ctx.strokeStyle='#244c3c';ctx.lineWidth=13;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineTo(...pt(e));ctx.stroke()};el.onpointerup=el.onpointercancel=()=>down=false}
