 on('pdfImport',startPDF,'onsubmit');on('cancelImport',()=>{cancelImport();toast('Đang dừng xử lý…')});on('getTemplate',()=>jsonDownload(templateCourse(),'hao-mau-goi-bai-hoc.json'));on('jsonImport',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>15*1024*1024)throw Error('Gói JSON vượt 15 MB.');const c=normalizeCourse(JSON.parse(await f.text()));draft={course:c,files:[],pages:[],hasText:true};render()}catch(e){toast(e.message);e.target.value=''}},'onchange');on('addDraftLesson',()=>{syncDraft();const n=Math.max(...draft.course.lessons.map(l=>l.number),0)+1;draft.course.lessons.push({id:'l'+String(n).padStart(2,'0'),number:n,title:'Bài '+n,start:1,end:1,words:[],grammar:[]});render()});$$('[data-remove-draft]').forEach(b=>b.onclick=()=>{syncDraft();draft.course.lessons.splice(+b.dataset.removeDraft,1);render()});on('discardDraft',()=>{draft=null;render()});on('commitImport',commitDraft);on('backup',backup);on('restore',restore,'onchange');on('exportCourse',()=>jsonDownload({...course(),documents:{}},'hao-'+courseId+'-bai-hoc.json'));
